-- Activity step templates by building type (Planning > Activity Library > Step Templates).
--
-- Same model as WBS and level templates (20261021000002 / 03): template_category = sector slug
-- (projects.category), building_types = building-type slugs (projects.building_type) the steps are
-- written for. No sector = common to every building type: the existing 70 trade templates stay common.
-- The step matcher and pickers prefer templates that fit the project (lib/template-fit.ts).
--
-- Seeds 48 templates for work the common set does not cover (villa roofs, PEB steel,
-- medical gases, asphalt, pipelines, ...). Weights total 100; scaled shares total 100 per template;
-- fixed steps are setting-out / test / curing days. Skipped where the same group + name exists, so
-- local edits are kept.

alter table public.activity_step_template_master
  add column if not exists template_category text,
  add column if not exists building_types text[] not null default '{}';

comment on column public.activity_step_template_master.template_category is
  'Sector slug (projects.category); null = common to every building type.';
comment on column public.activity_step_template_master.building_types is
  'Building-type slugs (projects.building_type) the steps are written for; empty = any in its sector.';

do $seed$
declare
  t jsonb;
  v_id uuid;
begin
