    continue when exists (
      select 1 from public.activity_step_template_master
       where group_name = t->>'group' and template_name = t->>'name');
    insert into public.activity_step_template_master
      (group_name, template_name, description, is_active, template_category, building_types)
    values (t->>'group', t->>'name', t->>'desc', true, nullif(t->>'cat', ''),
            array(select jsonb_array_elements_text(t->'types')))
    returning id into v_id;
    insert into public.activity_step_template_item
      (template_id, step_no, step_name, weight, discipline, resource_crew, est_duration_days,
       duration_basis, duration_share_pct, inspection_hold_point)
    select v_id, (i->>'step_no')::int, i->>'step_name', (i->>'weight')::numeric, i->>'discipline',
           i->>'resource_crew', nullif(i->>'est_duration_days', '')::numeric, i->>'duration_basis',
           nullif(i->>'duration_share_pct', '')::numeric, (i->>'inspection_hold_point')::boolean
    from jsonb_array_elements(t->'items') i;
  end loop;
